---@class UIFightTeamQuestInfoNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIFightTeamQuestInfoNode = Class("UIFightTeamQuestInfoNode")


function UIFightTeamQuestInfoNode:__init() 
    self._levelId = nil
    self._curLevelVo = nil
    self._curLevelType = nil
end


function UIFightTeamQuestInfoNode:__delete()
    self._levelId = nil
    self._curLevelVo = nil
    self._curLevelType = nil
end

function UIFightTeamQuestInfoNode:Awake()
    CfUtils.FillText(self.Text1, localize("推荐武装值"))
    CfUtils.FillText(self.Text2, localize("限制回合"))
end


function UIFightTeamQuestInfoNode:Start()
end


function UIFightTeamQuestInfoNode:Refresh(levelId)
    self._levelId      = checkInt(levelId)
    self._curLevelVo   = QuestConfMgr:GetInstance():GetQuestVoById(self._levelId)
    self._curLevelType = GoodsUtils.GetIdType(self._levelId, Constants.IDArea.Quests)     --关卡类型
    if not self._curLevelVo then
        return
    end

    local data = self._curLevelVo
    local type = self._curLevelType
    if (type == Constants.IDType.QuestTalent or 
        type == Constants.IDType.QuestTrainField or 
        type == Constants.IDType.QuestCardExperience or 
        type == Constants.IDType.ActivityQuestSkinExperience or
        type == Constants.IDType.QuestPatrolMaze or
        type == Constants.IDType.ClubBoss) then
        CfUtils.FillText(self.PowerNum, "----")
    else
        CfUtils.FillText(self.PowerNum, data.proposalLevel)
    end

    local roundNum = checkInt(data.rounds)
    if type == Constants.IDType.QuestPatrolMaze then
        roundNum = checkInt(data.battleRoundLimit)
    elseif type == Constants.IDType.ActivityCrisis then
        local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')
        local _roundNum = ActivityCrisisUtils.GetMaxRoundMember()
        roundNum = isNotNull(_roundNum) and _roundNum or checkInt(data.rounds)
    end
    CfUtils.FillText(self.LimitNum, roundNum)
    if checkNumber(roundNum) == 99 then
        CfUtils.SetActive(self.controller.gameObject.transform:Find("battleTarget/battleMaxNum"), false)
    end
end


function UIFightTeamQuestInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end


return UIFightTeamQuestInfoNode
